document.addEventListener("DOMContentLoaded",function(){const n=document.getElementById("keyword-addition");n.addEventListener("click",function(n){if(n.target.classList.contains("remove-input")){const t=n.target.closest(".govuk-form-group");t&&t.remove()}});const t=document.getElementById("add-another-keyword");t.addEventListener("click",function(){const i=n.querySelectorAll(".govuk-input").length,t=document.createElement("div");t.className="govuk-form-group";t.innerHTML=`
            <label class="govuk-label govuk-visually-hidden" for="keyword-${i}">Keywords</label>
            <div class="govuk-input__wrapper">
                <input class="govuk-input me-2" id="keyword-${i}" name="keyword" type="text">
                <button type="button" class="remove-input govuk-button govuk-button--secondary mb-0">Remove</button>  
            </div>
        `;n.appendChild(t)})});